          </mat-checkbox>
          @if (error('terms'); as msg) {
            <mat-error class="terms-error" data-testid="terms-error">{{ msg }}</mat-error>
          }
        </div>
      </form>

      <div class="button-row">
        <button mat-stroked-button type="button" data-testid="checkout-back-button" (click)="back()">Back</button>
        <button mat-flat-button type="button" data-testid="pay-button" [disabled]="processing()" (click)="pay()">
          {{ processing() ? 'Processing…' : 'Pay ' + total() + ' PLN' }}
        </button>
      </div>
    </div>
  `,
  styles: `
    .form {
      display: flex;
