interface Cell {
  row: number;
  start: number;
  end: number;
  couch: boolean;
  ids: string[];
}

interface Block {
  entrance: boolean;
  cells: Cell[];
}

interface RowModel {
  row: number;
  blocks: Block[];
}

const BLOCKS: [number, number][] = [
  [1, 4],
  [5, 20],
  [21, 24],
];

function buildRows(): RowModel[] {
  return Array.from({ length: ROW_COUNT }, (_, i) => {
    const row = i + 1;
    const blocks = BLOCKS.map(([from, to], blockIndex): Block => {
      if (blockIndex === 0 && row <= 10) return { entrance: true, cells: [] };
      const cells: Cell[] = [];
      if (row === COUCH_ROW) {
        for (let c = from; c < to; c += 2) {
          cells.push({ row, start: c, end: c + 1, couch: true, ids: [seatId(row, c), seatId(row, c + 1)] });
        }
      } else {
        for (let c = from; c <= to; c++) {
          cells.push({ row, start: c, end: c, couch: false, ids: [seatId(row, c)] });
        }
      }
      return { entrance: false, cells };
    });
    return { row, blocks };
  });
}

