    return date && parseIsoDate(date) && date >= this.todayIso ? date : this.todayIso;
  });
  protected readonly pickerValue = computed(() => {
    const selected = this.selected();
    return this.days.some((d) => d.iso === selected) ? null : parseIsoDate(selected);
  });

