          <button mat-stroked-button type="button" data-testid="cancel-button" (click)="cancel()">Cancel</button>
          <button mat-flat-button type="button" data-testid="continue-button" (click)="next(s.id)">Continue</button>
        </div>
      </div>
    }
  `,
  styles: `
    $cell: 36px;
    .auditorium {
      width: $cell * 30;
      margin: 0 auto;
    }
    .limit {
      text-align: center;
    }
    .screen {
      background: #9e9e9e;
      color: #fff;
      text-align: center;
      padding: 8px;
      margin: 0 $cell * 2 16px;
      border-radius: 4px 4px 50% 50% / 4px 4px 12px 12px;
      letter-spacing: 4px;
    }
    .seat-row {
      display: flex;
      align-items: center;
    }
    .row-label {
      width: $cell;
      text-align: center;
      font-size: 14px;
    }
    .aisle {
      width: $cell * 2;
      height: $cell;
    }
    .entrance {
      width: $cell * 4;
      height: $cell;
    }
    .cell {
      box-sizing: border-box;
      width: $cell - 4px;
      height: $cell - 4px;
      margin: 2px;
      padding: 0;
      border: 0;
      border-radius: 6px;
      font: inherit;
      font-size: 12px;
      color: #fff;
      cursor: pointer;
    }
    .couch {
      width: $cell * 2 - 4px;
      border-radius: 10px;
      border-bottom: 4px solid rgba(0, 0, 0, 0.35);
    }
    .cell[data-state='unavailable'] {
      cursor: not-allowed;
    }
    .cell[data-state='selected'],
    .swatch.selected {
      color: #000;
    }
    .cell[data-state='available'],
    .swatch.available {
      background-color: #2e7d32;
    }
    .cell[data-state='selected'],
    .swatch.selected {
      background-color: #f9a825;
    }
    .cell[data-state='unavailable'],
    .swatch.unavailable {
      background-color: #c62828;
    }
    .cell[data-state='accessible'],
    .swatch.accessible {
      background-color: #1565c0;
    }
    .legend {
      display: flex;
      justify-content: center;
      gap: 24px;
      margin: 16px 0;
    }
    .legend-item {
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .swatch {
      width: 20px;
      height: 20px;
      border-radius: 4px;
